steps.codeExample:
import { Hono } from "hono";
const app = new Hono();

app.post("/pedidos/:clienteId", async (c) => {
  const clienteId = c.req.param("clienteId");
  const body = await c.req.json();
  return c.json({ clienteId, item: body.item }, 201);
});

